    /**
     * Method to retrieve the Incident via IncidentFetchOneSummary
     * @param 	summary IncidentFetchOneSummary 
     * @return 	IncidentFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Incident getIncident( IncidentFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "IncidentFetchOneSummary arg cannot be null" );
    	
    	Incident entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Incident
        	// --------------------------------------
        	CompletableFuture<Incident> futureEntity = queryGateway.query(new FindIncidentQuery( new LoadIncidentFilter( summary.getIncidentId() ) ), ResponseTypes.instanceOf(Incident.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Incident with id " + summary.getIncidentId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


